"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["4512"],{31537(e){e.exports=JSON.parse('{"id":"V4-016","slug":"travel-insurance","term":"Travel Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Travel insurance is insurance that covers financial losses and costs that can arise when travelling, such as emergency medical treatment abroad, trip cancellation, lost luggage and travel delays.","explanation":["Travel insurance protects travellers against unexpected events that could be expensive, especially when abroad. The most important part is usually emergency medical cover, since treatment and repatriation in some countries can cost tens of thousands.","Policies typically cover medical expenses and emergency evacuation, cancelling or cutting short a trip for covered reasons such as illness or bereavement, lost, stolen or delayed baggage, missed departures and personal liability. They can be bought for a single trip or as an annual policy covering multiple trips.","For example, a traveller who breaks a leg skiing abroad might face large hospital bills and the cost of a special flight home. Travel insurance with medical and winter sports cover would pay these costs, minus any excess.","Exclusions are common. Many policies exclude pre-existing medical conditions unless declared, claims linked to alcohol, high-risk activities unless extra cover is bought, and travel to places against official government advice. Some countries have reciprocal healthcare arrangements, but these rarely cover everything, so travel insurance is still widely recommended."],"note":"","total":1725,"prev":{"slug":"transmission-mechanism","term":"Transmission Mechanism"},"next":{"slug":"treasury-bill","term":"Treasury Bill"}}')}}]);